#!/usr/bin/env node

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { legacyRedirects } from '../src/data/legacy-redirects.mjs';

const outputPath = fileURLToPath(new URL('../public/_redirects', import.meta.url));

export function renderCloudflareRedirects(redirects) {
  const lines = [
    '# Generated by npm run generate:redirects. Do not edit manually.',
    `# ${redirects.length} logical aliases; both trailing-slash forms are preserved.`,
    ''
  ];

  for (const { source, destination } of redirects) {
    lines.push(
      `${source} ${destination} 301`,
      `${source}/ ${destination} 301`
    );
  }

  return `${lines.join('\n')}\n`;
}

function main(argv) {
  const check = argv.includes('--check');
  const unknownArguments = argv.filter((argument) => argument !== '--check');
  if (unknownArguments.length > 0) {
    throw new Error(`Unknown argument: ${unknownArguments[0]}`);
  }

  const expected = renderCloudflareRedirects(legacyRedirects);
  if (check) {
    const actual = fs.existsSync(outputPath)
      ? fs.readFileSync(outputPath, 'utf8')
      : null;
    if (actual !== expected) {
      throw new Error(
        'public/_redirects is stale. Run npm run generate:redirects and commit the result.'
      );
    }
    console.log(`Verified ${legacyRedirects.length} Cloudflare redirect aliases.`);
    return;
  }

  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, expected);
  console.log(`Wrote ${legacyRedirects.length} Cloudflare redirect aliases.`);
}

if (
  process.argv[1] &&
  path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  main(process.argv.slice(2));
}
